// ExplorerFrame's localized folder-empty caption (resource-only, never a
// hardcoded English fallback). The resource identifier is owned by Windows.
constexpr UINT kExplorerEmptyFolderStringId = 41478;
std::wstring g_emptyFolderCaption;
std::once_flag g_emptyCaptionOnce;

void LoadExplorerEmptyFolderCaption() {
    g_emptyFolderCaption.clear();
    auto readResource = [](HMODULE module) -> std::wstring {
        if (!module) return {};
        wchar_t buffer[256]{};
        const int length = LoadStringW(module, kExplorerEmptyFolderStringId,
            buffer, static_cast<int>(sizeof(buffer) / sizeof(buffer[0])));
        return length > 0 ? std::wstring(buffer, length) : std::wstring{};
    };
    // Reuse Explorer's already-loaded module when available. Otherwise, or
    // if it lacks this string, try Windows' explicit MUI-aware datafile load.
    g_emptyFolderCaption = readResource(GetModuleHandleW(L"ExplorerFrame.dll"));
    if (g_emptyFolderCaption.empty()) {
        wchar_t directory[MAX_PATH]{};
        const UINT length = GetSystemDirectoryW(directory, MAX_PATH);
        if (length != 0 && length < MAX_PATH) {
            std::wstring modulePath(directory, length);
            modulePath += L"\\ExplorerFrame.dll";
            HMODULE module = LoadLibraryExW(modulePath.c_str(), nullptr,
                LOAD_LIBRARY_AS_DATAFILE | LOAD_LIBRARY_AS_IMAGE_RESOURCE);
            g_emptyFolderCaption = readResource(module);
            if (module) FreeLibrary(module);
        }
    }
    // Do not substitute English when the resource is absent on a new build.
    // A missing private resource should fail closed rather than mislocalize.
}
